settings.custom_liquid:
{%- assign mf = product.metafields.custom -%}
<style>
.sa-acc{margin-top:8px}.sa-acc details{border-top:1px solid rgba(27,31,36,.15)}.sa-acc details:last-child{border-bottom:1px solid rgba(27,31,36,.15)}
.sa-acc summary{cursor:pointer;padding:14px 0;font-weight:600;font-size:1.05rem;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:12px}
.sa-acc summary::-webkit-details-marker{display:none}.sa-acc summary::after{content:"+";font-size:1.5rem;line-height:1;color:#C8552B;flex:none}
.sa-acc details[open]>summary::after{content:"\2013"}.sa-acc .sa-body{padding:0 0 16px}.sa-acc .sa-body>:first-child{margin-top:0}
.sa-acc table{width:100%;border-collapse:collapse;font-size:.95rem}.sa-acc td,.sa-acc th{padding:8px 6px;border-bottom:1px solid rgba(27,31,36,.1);text-align:left;vertical-align:top}
mark.a-verifier{background:#FFE58A;padding:0 3px}
</style>
<div class="sa-acc rte">
{%- if mf.specifications.value != blank -%}<details open><summary>Dimensions et caractéristiques</summary><div class="sa-body">{{ mf.specifications.value }}</div></details>{%- endif -%}
{%- if mf.declarer.value != blank -%}<details><summary>Faut-il le déclarer ?</summary><div class="sa-body">{{ mf.declarer.value }}</div></details>{%- endif -%}
{%- if mf.montage_texte.value != blank -%}<details><summary>Montage</summary><div class="sa-body">{{ mf.montage_texte.value }}</div></details>{%- endif -%}
{%- if mf.ancrage_vent.value != blank -%}<details><summary>Ancrage et vent</summary><div class="sa-body">{{ mf.ancrage_vent.value }}</div></details>{%- endif -%}
{%- if mf.ne_fait_pas.value != blank -%}<details><summary>Ce qu'il ne fait pas</summary><div class="sa-body">{{ mf.ne_fait_pas.value }}</div></details>{%- endif -%}
{%- if mf.livraison_texte.value != blank -%}<details><summary>Livraison</summary><div class="sa-body">{{ mf.livraison_texte.value }}</div></details>{%- endif -%}
{%- if mf.contenu_colis.value != blank -%}<details><summary>Contenu du colis</summary><div class="sa-body">{{ mf.contenu_colis.value }}</div></details>{%- endif -%}
</div>

{%- if product.metafields.custom.protege.value != blank -%}
<div class="page-width rte">
  <h2>Ce qu'il protège</h2>
  {{ product.metafields.custom.protege.value }}
</div>
{%- endif -%}

{%- if product.metafields.custom.faq.value != blank -%}
<div class="page-width rte">
  <h2>Questions fréquentes sur ce produit</h2>
  {{ product.metafields.custom.faq.value }}
</div>
{%- endif -%}
